// Typed wrapper around the Swiss Ephemeris WASM build (see tools/build-sweph.sh).
// Ephemeris files (.se1) are loaded on demand: we probe a calculation, read the
// "file not found" message Swiss Ephemeris returns, fetch that file and retry.
// @ts-expect-error generated by emscripten, no types
import createSweph from './wasm/sweph.mjs';

export const SE = {
  SUN: 0, MOON: 1, MERCURY: 2, VENUS: 3, MARS: 4, JUPITER: 5, SATURN: 6,
  URANUS: 7, NEPTUNE: 8, PLUTO: 9, MEAN_NODE: 10, TRUE_NODE: 11,
  ECL_NUT: -1,
  // flags
  FLG_SWIEPH: 2, FLG_MOSEPH: 4, FLG_SPEED: 256, FLG_NOGDEFL: 512,
  FLG_NOABERR: 1024, FLG_TRUEPOS: 16, FLG_NONUT: 64, FLG_EQUATORIAL: 2048,
  FLG_TOPOCTR: 32 * 1024, FLG_SIDEREAL: 64 * 1024,
  GREG_CAL: 1, JUL_CAL: 0,
  // rise/set
  CALC_RISE: 1, CALC_SET: 2, CALC_MTRANSIT: 4, CALC_ITRANSIT: 8,
  BIT_DISC_CENTER: 256, BIT_DISC_BOTTOM: 8192, BIT_NO_REFRACTION: 512,
  BIT_HINDU_RISING: 256 | 512 | 128 * 1024,
} as const;

export interface Position {
  lon: number; lat: number; dist: number;
  speedLon: number; speedLat: number; speedDist: number;
  /** flags actually used; check FLG_SWIEPH to know file-based precision was used */
  flags: number;
}

export interface Houses { cusps: number[]; ascmc: number[]; cuspSpeeds: number[]; ascmcSpeeds: number[] }

export type FileFetcher = (name: string) => Promise<Uint8Array | null>;

const EPHE_DIR = '/ephe';

export class Sweph {
  private m: any;
  private fetcher: FileFetcher;
  private loaded = new Set<string>();
  private missing = new Set<string>();
  private buf: number;   // scratch: 64 doubles
  private ibuf: number;  // scratch: 16 ints
  private serr: number;  // 256-byte error string

  constructor(module: any, fetcher: FileFetcher) {
    this.m = module;
    this.fetcher = fetcher;
    this.buf = module._malloc(8 * 64);
    this.ibuf = module._malloc(4 * 16);
    this.serr = module._malloc(256);
    module.FS.mkdir(EPHE_DIR);
    this.withString(EPHE_DIR, (p) => module._swe_set_ephe_path(p));
  }

  version(): string {
    this.m._swe_version(this.serr);
    return this.m.UTF8ToString(this.serr);
  }

  private withString<T>(s: string, fn: (ptr: number) => T): T {
    const n = this.m.lengthBytesUTF8(s) + 1;
    const p = this.m._malloc(n);
    this.m.stringToUTF8(s, p, n);
    try { return fn(p); } finally { this.m._free(p); }
  }

  private f64(i: number): number { return this.m.HEAPF64[(this.buf >> 3) + i]; }
  private err(): string { return this.m.UTF8ToString(this.serr); }

  /** Add an ephemeris file to the virtual file system. */
  addFile(name: string, data: Uint8Array): void {
    this.m.FS.writeFile(`${EPHE_DIR}/${name}`, data);
    this.loaded.add(name);
    this.m._swe_close();
    this.withString(EPHE_DIR, (p) => this.m._swe_set_ephe_path(p));
  }

  /**
   * Make sure the planet and moon files covering `jd` are loaded.
   * Call before synchronous calculations for a new date range.
   */
  async ensureEphemeris(jdUt: number): Promise<void> {
    for (let attempt = 0; attempt < 4; attempt++) {
      const need = new Set<string>();
      for (const body of [SE.MOON, SE.SATURN]) {
        this.calcRaw(jdUt, body, SE.FLG_SWIEPH);
        const m = /SwissEph file '([^']+)' not found/.exec(this.err());
        if (m && !this.missing.has(m[1])) need.add(m[1]);
      }
      if (need.size === 0) return;
      for (const name of need) {
        const data = await this.fetcher(name);
        if (data) this.addFile(name, data);
        else this.missing.add(name); // out of range: Swiss falls back to Moshier
      }
    }
  }

  private calcRaw(jdUt: number, body: number, flags: number): number {
    return this.m._swe_calc_ut(jdUt, body, flags, this.buf, this.serr);
  }

  calcUt(jdUt: number, body: number, flags: number): Position {
    const ret = this.calcRaw(jdUt, body, flags | SE.FLG_SPEED);
    if (ret < 0) throw new Error(`swe_calc_ut(${body}): ${this.err()}`);
    return {
      lon: this.f64(0), lat: this.f64(1), dist: this.f64(2),
      speedLon: this.f64(3), speedLat: this.f64(4), speedDist: this.f64(5),
      flags: ret,
    };
  }

  julday(y: number, mo: number, d: number, hour: number, gregorian = true): number {
    return this.m._swe_julday(y, mo, d, hour, gregorian ? SE.GREG_CAL : SE.JUL_CAL);
  }

  revjul(jd: number, gregorian = true): { year: number; month: number; day: number; hour: number } {
    const ip = this.ibuf >> 2;
    this.m._swe_revjul(jd, gregorian ? 1 : 0, this.ibuf, this.ibuf + 4, this.ibuf + 8, this.buf);
    const H = this.m.HEAP32;
    return { year: H[ip], month: H[ip + 1], day: H[ip + 2], hour: this.f64(0) };
  }

  deltaT(jdUt: number, flags = SE.FLG_SWIEPH): number {
    return this.m._swe_deltat_ex(jdUt, flags, this.serr);
  }

  setSidMode(mode: number, t0 = 0, ayanT0 = 0): void {
    this.m._swe_set_sid_mode(mode, t0, ayanT0);
  }

  ayanamsaUt(jdUt: number, flags: number): number {
    const ret = this.m._swe_get_ayanamsa_ex_ut(jdUt, flags, this.buf, this.serr);
    if (ret < 0) throw new Error(`swe_get_ayanamsa_ex_ut: ${this.err()}`);
    return this.f64(0);
  }

  setTopo(lon: number, lat: number, altM: number): void {
    this.m._swe_set_topo(lon, lat, altM);
  }

  /** Houses for tropical or sidereal flags; hsys is a one-letter code like 'P'. */
  houses(jdUt: number, flags: number, lat: number, lon: number, hsys: string): Houses {
    const m = this.m;
    const cusps = m._malloc(8 * 37), ascmc = m._malloc(8 * 10);
    const cs = m._malloc(8 * 37), as = m._malloc(8 * 10);
    try {
      m._swe_houses_ex2(jdUt, flags, lat, lon, hsys.charCodeAt(0), cusps, ascmc, cs, as, this.serr);
      const H = m.HEAPF64;
      const arr = (p: number, n: number) => Array.from(H.subarray(p >> 3, (p >> 3) + n)) as number[];
      return { cusps: arr(cusps, 13), ascmc: arr(ascmc, 10), cuspSpeeds: arr(cs, 13), ascmcSpeeds: arr(as, 10) };
    } finally {
      [cusps, ascmc, cs, as].forEach((p) => m._free(p));
    }
  }

  /** Rise/set/transit time (JD UT) after jdUt, or null when the body doesn't rise/set. */
  riseTrans(jdUt: number, body: number, rsmi: number, flags: number,
            geo: { lon: number; lat: number; alt: number }, pressure = 0, temp = 0): number | null {
    const g = this.m._malloc(8 * 3);
    const H = this.m.HEAPF64;
    H[g >> 3] = geo.lon; H[(g >> 3) + 1] = geo.lat; H[(g >> 3) + 2] = geo.alt;
    try {
      const ret = this.m._swe_rise_trans(jdUt, body, 0, flags, rsmi, g, pressure, temp, this.buf, this.serr);
      if (ret === -1) throw new Error(`swe_rise_trans: ${this.err()}`);
      return ret === -2 ? null : this.f64(0);
    } finally { this.m._free(g); }
  }

  /** Fixed star position by name (e.g. "Spica"). Needs sefstars.txt in the file system. */
  fixstarUt(name: string, jdUt: number, flags: number): Position & { name: string } {
    const p = this.m._malloc(64);
    this.m.stringToUTF8(name, p, 64);
    try {
      const ret = this.m._swe_fixstar2_ut(p, jdUt, flags | SE.FLG_SPEED, this.buf, this.serr);
      if (ret < 0) throw new Error(`swe_fixstar2_ut(${name}): ${this.err()}`);
      return {
        name: this.m.UTF8ToString(p), lon: this.f64(0), lat: this.f64(1), dist: this.f64(2),
        speedLon: this.f64(3), speedLat: this.f64(4), speedDist: this.f64(5), flags: ret,
      };
    } finally { this.m._free(p); }
  }

  /** Next time (JD UT) after jdUt when the Sun reaches longitude x2cross. */
  solcrossUt(x2cross: number, jdUt: number, flags: number): number {
    const jd = this.m._swe_solcross_ut(x2cross, jdUt, flags, this.serr);
    if (jd < jdUt) throw new Error(`swe_solcross_ut: ${this.err()}`);
    return jd;
  }

  mooncrossUt(x2cross: number, jdUt: number, flags: number): number {
    const jd = this.m._swe_mooncross_ut(x2cross, jdUt, flags, this.serr);
    if (jd < jdUt) throw new Error(`swe_mooncross_ut: ${this.err()}`);
    return jd;
  }
}

export async function loadSweph(fetcher: FileFetcher, moduleOverrides: object = {}): Promise<Sweph> {
  const module = await createSweph(moduleOverrides);
  return new Sweph(module, fetcher);
}
